    text = str(task or "").lower()
    if re.search(r"\b(register|sign up|signup|create account)\b", text):
        return False
    if re.search(r"\b(log ?in|sign in|authenticate)\b", text):
        return True
    account_terms = (
        "watchlist",
        "wishlist",
        "profile",
        "account",
        "saved",
        "add film",
        "delete film",
        "edit film",
        "edit user",
        "modify your profile",
    )
    return any(term in text for term in account_terms)

